// undo-stack | undo-history / deque | duplicates / p3
// Documented reference implementation.

import java.util.ArrayDeque;
import java.util.Deque;

public final class Demo {
    private final Deque<String> history = new ArrayDeque<>();
    private final int limit = 3;

    void apply_doc(String action) {
        history.push(action);
        while (history.size() > limit) {
            history.removeLast();
        }
    }

    String undo() {
        return history.isEmpty() ? "<vazio>" : history.pop();
    }

    public static void main(String[] args) {
        Demo demo = new Demo();
        for (int i = 0; i < 8; i++) {
            demo.apply_doc("action-" + i);
        }
        System.out.println("undo=" + demo.undo());
        System.out.println("restantes=" + demo.history.size());
    }
}

// word-frequency | count-occurrences / split-and-map | large / p3

import java.util.LinkedHashMap;
import java.util.Map;

public final class Demo {
    static Map<String, Integer> countWords(String text) {
        Map<String, Integer> counts = new LinkedHashMap<>();
        String normalized = text.toLowerCase().replaceAll("[^a-z0-9 ]", " ");
        for (String word : normalized.trim().split("\\s+")) {
            if (word.isEmpty()) continue;
            counts.merge(word, 1, Integer::sum);
        }
        return counts;
    }

    public static void main(String[] args) {
        String text = "gamma gamma code review gamma gamma";
        countWords(text).entrySet().stream()
            .filter(e -> e.getValue() >= 3)
            .forEach(e -> System.out.printf("%s:%d%n", e.getKey(), e.getValue()));
    }
}

// summary | aggregate / stream | negative / p2
// Explicit naming and direct control flow.

import java.util.Arrays;
import java.util.stream.IntStream;

public final class Demo {
    public record Summary(long total, int count, double average) {}

    static Summary summarize_explicit(int[] values) {
        long total = IntStream.of(values).asLongStream().sum();
        int count = values.length;
        double average = count == 0 ? 0.0 : (double) total / count;
        return new Summary(total, count, average);
    }

    public static void main(String[] args) {
        int[] sample = {-10, -2, 0, 10, 11};
        Summary summary = summarize_explicit(sample);
        System.out.printf("total=%d average=%.2f%n", summary.total(), summary.average());
        System.out.println(Arrays.toString(sample));
    }
}
